debug.error_function_source:
async def act(page):
    import asyncio
    import csv
    import io
    import re
    from datetime import datetime

    # 1) Ensure any blocking modal is dismissed by pressing Escape a couple times
    try:
        await page.keyboard.press('Escape')
        await asyncio.sleep(0.35)
        await page.keyboard.press('Escape')
        await asyncio.sleep(0.35)
    except Exception:
        pass

    # 2) Locate the toolbar row using the exact accessible name shown in the accessibility tree.
    toolbar_row_name = (
        "Page Go to Previous page 1 Go to Next page of 18 pages | View 20 per page| Total 354 records found |New Order RSS Export to: CSV Export Reset Filter Search"
    )

    toolbar_row = None
    tables = page.get_by_role("table")
    if await tables.count() == 0:
        raise RuntimeError("No tables found on page; cannot locate Orders toolbar")

    for i in range(await tables.count()):
        t = tables.nth(i)
        rows = t.get_by_role("row", name=toolbar_row_name)
        if await rows.count() > 0:
            toolbar_row = rows.nth(0)
            break

    if toolbar_row is None:
        # final fallback: find a row that contains the substring 'Export to: CSV'
        rows_all = page.get_by_role("row")
        for i in range(await rows_all.count()):
            r = rows_all.nth(i)
            try:
                txt = await r.inner_text()
            except Exception:
                continue
            if 'Export to' in (txt or ''):
                toolbar_row = r
                break

    if toolbar_row is None:
        raise RuntimeError("Could not find the Orders toolbar row containing Export controls")

    # 3) From the toolbar_row, get the Export cell
    export_cell = None
    try:
        cells = toolbar_row.get_by_role("cell")
        # Prefer exact-named cell
        for j in range(await cells.count()):
            c = cells.nth(j)
            try:
                name = await c.get_attribute('aria-label')
            except Exception:
                name = None
            # Try to detect by accessible name or visible text
            try:
                visible = await c.inner_text()
            except Exception:
                visible = ''
            if (name and 'Export to' in name) or ('Export to' in (visible or '')):
                export_cell = c
                break
    except Exception:
        export_cell = None

    if export_cell is None:
        # fallback: any cell that contains the text 'Export to'
        candidates = page.get_by_role("cell").filter(has_text="Export to")
        if await candidates.count() > 0:
            export_cell = candidates.nth(0)

    if export_cell is None:
        raise RuntimeError("Could not locate Export cell")

    # 4) Ensure CSV is selected in the combobox if possible
    try:
        if await export_cell.get_by_role("combobox").count() > 0:
            combobox = export_cell.get_by_role("combobox").nth(0)
            try:
                # select by visible option label
                await combobox.select_option(label="CSV")
            except Exception:
                # fallback: pick an option whose visible text contains 'csv'
                try:
                    opts = combobox.get_by_role("option")
                    if await opts.count() > 0:
                        texts = await opts.all_inner_texts()
                        chosen = None
                        for t in texts:
                            if 'csv' in (t or '').lower():
                                chosen = t
                                break
                        if chosen is not None:
                            await combobox.select_option(label=chosen)
                except Exception:
                    try:
                        await combobox.select_option(value='csv')
                    except Exception:
                        pass
    except Exception:
        # ignore and continue; default may already be CSV
        pass

    # 5) Locate the Export button inside the export_cell and attempt to click while capturing download
    export_button = None
    try:
        if await export_cell.get_by_role("button", name="Export").count() > 0:
            export_button = export_cell.get_by_role("button", name="Export").nth(0)
    except Exception:
        export_button = None

    if export_button is None:
        # fallback: any page-level button that contains 'Export'
        btns = page.get_by_role("button").filter(has_text="Export")
        if await btns.count() > 0:
            export_button = btns.nth(0)

    if export_button is None:
        raise RuntimeError("Could not find Export button")

    # Try clicking; if blocked, retry after dismissing modal; as a last resort call the grid export JS directly
    dl = None
    try:
        download_ctx = page.expect_download()
        await export_button.click()
        dl = await download_ctx
    except Exception:
        # Try to close modal again and retry
        try:
            await page.keyboard.press('Escape')
            await asyncio.sleep(0.5)
            download_ctx = page.expect_download()
            await export_button.click()
            dl = await download_ctx
        except Exception:
            # Last resort: invoke the known grid export JS if present
            try:
                # many Magento grids expose a JS object like sales_order_gridJsObject.doExport()
                await page.evaluate("() => { if (window.sales_order_gridJsObject && typeof window.sales_order_gridJsObject.doExport === 'function') { window.sales_order_gridJsObject.doExport(); } }")
                # wait briefly for download to start and capture it
                dl = await page.wait_for_event('download', timeout=15000)
            except Exception as e:
                raise RuntimeError(f"Failed to trigger export: {e}")

    # 6) Save the download to disk
    filename = 'orders_export.csv'
    try:
        await dl.save_as(filename)
    except Exception:
        # If save_as fails, try to get path attribute
        try:
            path = dl.path()
            if path:
                filename = path
        except Exception:
            pass

    # 7) Read and decode the CSV (UTF-8 primary, latin-1 fallback)
    with open(filename, 'rb') as f:
        raw = f.read()
    try:
        text = raw.decode('utf-8')
    except Exception:
        text = raw.decode('latin-1')

    # 8) Parse CSV
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    if not rows or len(rows) < 2:
        print("0.00")
        return

    headers = [h.strip() for h in rows[0]]

    def find_col(candidates):
        for i, h in enumerate(headers):
            hl = (h or '').lower()
            for c in candidates:
                if c in hl:
                    return i
        return None

    status_idx = find_col(['status', 'state'])
    customer_idx = find_col(['bill to name', 'bill to', 'customer'])
    date_idx = find_col(['purchased on', 'created', 'date'])
    grand_idx = find_col(['g.t. (purchased)', 'g.t. (base)', 'g.t.', 'grand total', 'total'])

    # Build data rows as dicts
    data_rows = []
    for r in rows[1:]:
        if len(r) < len(headers):
            r = r + [''] * (len(headers) - len(r))
        data_rows.append({headers[i]: (r[i] or '').strip() for i in range(len(headers))})

    # 9) Filter cancelled orders (status contains 'cancel')
    cancelled = []
    for r in data_rows:
        st = ''
        if status_idx is not None:
            st = r[headers[status_idx]]
        if 'cancel' in (st or '').lower():
            cust = ''
            if customer_idx is not None:
                cust = r[headers[customer_idx]]
            if not cust:
                # fallback to any email-like column
                for h in headers:
                    if 'email' in h.lower():
                        cust = r[h]
                        break
            cancelled.append({'row': r, 'customer': cust or '(guest)'} )

    if not cancelled:
        print("0.00")
        return

    # 10) Count cancellations per customer
    counts = {}
    for c in cancelled:
        k = c['customer']
        counts[k] = counts.get(k, 0) + 1

    max_count = max(counts.values())
    candidates = [k for k, v in counts.items() if v == max_count]
    # deterministic tie-break
    target_customer = sorted(candidates)[0]

    # 11) Collect cancelled orders for that customer
    cust_rows = [c['row'] for c in cancelled if c['customer'] == target_customer]

    # 12) Parse dates to find most recent cancelled order(s)
    def parse_date(val):
        if not val:
            return None
        s = val.strip()
        fmts = [
            "%b %d, %Y %I:%M:%S %p",
            "%B %d, %Y %I:%M:%S %p",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
        ]
        for f in fmts:
            try:
                return datetime.strptime(s, f)
            except Exception:
                pass
        try:
            return datetime.fromisoformat(s.replace(' ', 'T'))
        except Exception:
            return None

    dated = []
    for r in cust_rows:
        dval = ''
        if date_idx is not None:
            dval = r[headers[date_idx]]
        parsed = parse_date(dval)
        dated.append((parsed, r))

    dated_with = [d for d in dated if d[0] is not None]
    if dated_with:
        dated_with.sort(key=lambda x: x[0], reverse=True)
        most_recent_ts = dated_with[0][0]
        most_recent_rows = [row for (p, row) in dated_with if p == most_recent_ts]
    else:
        most_recent_rows = [cust_rows[-1]]

    # 13) Sum grand totals for the most recent cancelled order(s)
    def parse_money(s):
        if not s:
            return 0.0
        t = s.strip().replace('\u00A0', ' ')
        t = t.replace('$', '').replace('€', '').replace('£', '')
        t = t.replace(',', '')
        m = re.search(r"-?[0-9]+(?:\.[0-9]+)?", t)
        if not m:
            return 0.0
        try:
            return float(m.group(0))
        except Exception:
            return 0.0

    total = 0.0
    for r in most_recent_rows:
        raw = ''
        if grand_idx is not None:
            raw = r[headers[grand_idx]]
        else:
            for h in headers:
                if 'total' in (h or '').lower() or 'g.t.' in (h or '').lower():
                    raw = r[h]
                    break
        total += parse_money(raw)

    # 14) Print the numeric result only (two decimals)
    print(f"{total:.2f}")
